CREATE TABLE receipts(domain TEXT NOT NULL CHECK(domain='zos.core01b.synthetic.v1'), request TEXT NOT NULL CHECK(request='fixture-request-0001'), message TEXT NOT NULL UNIQUE, signature TEXT NOT NULL CHECK(length(signature)=128), artifact TEXT NOT NULL CHECK(length(artifact)=64), operation TEXT NOT NULL CHECK(operation='treasury:debit:7'), issuer TEXT NOT NULL CHECK(length(issuer)=64), authority TEXT NOT NULL CHECK(authority='treasury'), PRIMARY KEY(domain,request), FOREIGN KEY(domain,request) REFERENCES effects(domain,request) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE effects(domain TEXT NOT NULL CHECK(domain='zos.core01b.synthetic.v1'), request TEXT NOT NULL CHECK(request='fixture-request-0001'), delta INTEGER NOT NULL CHECK(delta=-7), PRIMARY KEY(domain,request), FOREIGN KEY(domain,request) REFERENCES receipts(domain,request) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE VIEW treasury AS SELECT 100+COALESCE(SUM(delta),0) AS balance FROM effects;
